import { render, screen } from '@testing-library/react';
import { derive } from '../domain/derive';
import { sampleDoc } from '../domain/fixture';
import { DEFAULT_PREFS } from '../domain/transpose';
import NotePanel from './NotePanel';

function panel() {
  const doc = sampleDoc('asax');
  const derived = derive(doc, DEFAULT_PREFS);
  render(<NotePanel doc={doc} derived={derived} id={doc.score[0].ev[0].id} onEdit={() => {}} />);
}

describe('NotePanel', () => {
  // WCAG 2.5.3: a button's name must contain its visible text. The glyph is generated by CSS from data-glyph, so the
  // button holds no text of its own and keeps the spoken name.
  it.each([['Octave down', '−8'], ['Semitone down', '−1'], ['Semitone up', '+1'], ['Octave up', '+8']])(
    '%s: the name is spoken, the glyph %s is generated content',
    (name, glyph) => {
      panel();
      const button = screen.getByRole('button', { name });
      expect(button).toHaveTextContent('');
      expect(button.querySelector('[aria-hidden="true"]')).toHaveAttribute('data-glyph', glyph);
    },
  );

  it('draws the 3 of the triplet button as a path, not as text', () => {
    panel();
    const button = screen.getByRole('button', { name: 'Triplet' });
    expect(button.querySelector('text')).toBeNull();
    expect(button.querySelector('svg path')).not.toBeNull();
  });
});
